namespace Markwardt.AssetPipeline.Client.ViewModels;

/// <summary>
/// An <see cref="AssetVariantViewModel"/> generated by a <see cref="TextNodeViewModel"/>.
/// </summary>
internal sealed partial class TextVariantViewModel : AssetVariantViewModel
{
    /// <summary>
    /// Initializes a new instance of the <see cref="TextVariantViewModel"/> class.
    /// </summary>
    public TextVariantViewModel(string id, string name, VariantStatus status, DateTimeOffset createdAt, string? errorMessage = null)
        : base(id, name, status, createdAt, errorMessage)
    {
    }

    [ObservableProperty]
    private string? outputFilePath;

    /// <inheritdoc />
    public override AssetVariant ToModel() => new TextVariant
    {
        Id = Id,
        Name = Name,
        Status = Status,
        CreatedAt = CreatedAt,
        ErrorMessage = ErrorMessage,
        OutputFilePath = OutputFilePath,
    };

    partial void OnOutputFilePathChanged(string? value) => RaiseChanged();
}
